{
  "criteria": [
    {
      "id": "C1",
      "level": "Accomplished",
      "mark": 7,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "The spacecraft is intended to image and send data to ground stations for collation and analysis."
        },
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        },
        {
          "where": "Introduction",
          "quote": "The proposed satellite would likely be used by governmental and science agencies (e.g. CSIRO, BOM) for research and/or education."
        }
      ],
      "reasoning": "The report explains the Australian reef-monitoring need, primary imaging mission, and rationale for one spacecraft. It identifies likely government and science users, but does not clearly distinguish the mission operator from customers or specify a definite operator. The rationale and user descriptions are useful but not fully detailed or consistently supported by references."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "The proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "Specifically, an altitude of 600km requires a mean inclination of $ 97.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost ten minutes was achieved, in addition to the already frequent amount of passes."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "A span of five years is a sound estimate of the useful lifespan of the proposed satellite."
        }
      ],
      "reasoning": "The report covers launch, orbit elements, STK access analysis, a five-year duration, and a passive drag-sail EOL concept, with useful screenshots and tabulated results. However, the launch choice is speculative, mission performance is not tied to sensor resolution or data needs, and the STK access output contains apparent inconsistencies. Some orbital and sunlight claims are inaccurate, and EOL implementation is not substantiated with calculations or software files."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "Thus, launch may need to be adjusted if the rocket is still not constructed by the proposed date."
        }
      ],
      "reasoning": "The conclusion summarizes the selected launch, orbit, and ground station and acknowledges launch uncertainty. It reaches relevant but mostly generic conclusions and does not critically assess whether the design meets imaging, revisit, or data-delivery needs."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Bibliography",
          "quote": "[6] https://en.wikipedia.org/wiki/2021_in_spaceflight. [Online]."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "The first fifteen access periods are listed above."
        }
      ],
      "reasoning": "The report has the expected sections and a broadly logical structure, and includes useful visual and tabular material. Presentation is weakened by grammar and typographical issues, inconsistent or absent figure/table numbering and titles, awkwardly rendered tables, and incomplete web-reference formatting. Wikipedia is used as a source despite the task's restriction."
    }
  ],
